sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float threshold;
uniform float high;
uniform float softness;
uniform float invert;
uniform float style;
uniform float weighting;
half4 main(float2 coord) {
    half4 c = image.eval(coord);
    float3 rgb = float3(unpremul(c).rgb);
    float lum = dot(rgb, float3(0.2126, 0.7152, 0.0722));
    float m = weighting > 1.5 ? 0.625 * sqrt(dot(rgb, rgb) / 3.0) : weighting > 0.5 ? 0.806 * lum : lum;
    float keep = softness > 0.0 ? smoothstep(threshold, threshold + softness + 0.0001, m) : step(threshold, m);
    if (weighting > 1.5) lum = 0.775 * sqrt(dot(rgb, rgb) / 3.0);
    if (style > 0.5) {
        float n = length(float3(unpremul(c).rgb));
        keep = softness > 0.0 ? smoothstep(threshold - softness, threshold + 0.0001, n) : step(threshold, n);
    }
    if (high < 1.0) keep *= softness > 0.0 ? 1.0 - smoothstep(high, high + softness + 0.0001, lum) : step(lum, high);
    return c * (invert > 0.5 ? 1 - keep : keep);
}
